// SPDX-License-Identifier: Apache-2.0
// ck seed for FlashInfer-Bench/004_gemm_n128_k2048.
//
// Exists to prove the Composable Kernel path end to end: a submission that
// instantiates a CK device op, compiles against the CK header tree the
// packager puts on the include path, and passes the AMD-derived tolerance.
// The tile configuration is CK's own stock fp16 XDL instance -- it is a path
// test, not a tuned kernel, and at N=128 it wastes most of each tile.
//
// The problem is C[M,N] = A[M,K] @ B[N,K]^T. A row-major NxK buffer is a
// column-major KxN buffer, so B enters CK as ColumnMajor with stride K and
// no transpose is needed anywhere.
//
// GemmSpecialization::MNKPadding is load-bearing: M is a benchmark axis and
// takes values as small as 1, far below MPerBlock. The unpadded specialization
// does not reject those shapes at compile time -- IsSupportedArgument() would
// refuse them at run time, one workload at a time.
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <c10/hip/HIPStream.h>

#include "ck/ck.hpp"
#include "ck/stream_config.hpp"
#include "ck/tensor_operation/gpu/device/gemm_specialization.hpp"
#include "ck/tensor_operation/gpu/device/impl/device_gemm_xdl_cshuffle.hpp"
#include "ck/tensor_operation/gpu/device/tensor_layout.hpp"
#include "ck/tensor_operation/gpu/element/element_wise_operation.hpp"

#include <stdexcept>

namespace {

using F16 = ck::half_t;
using F32 = float;

using Row = ck::tensor_layout::gemm::RowMajor;
using Col = ck::tensor_layout::gemm::ColumnMajor;
using PassThrough = ck::tensor_operation::element_wise::PassThrough;

static constexpr auto kSpec =
    ck::tensor_operation::device::GemmSpecialization::MNKPadding;

template <ck::index_t... Is>
using S = ck::Sequence<Is...>;

using DeviceGemmInstance = ck::tensor_operation::device::DeviceGemm_Xdl_CShuffle<
    Row, Col, Row,
    F16, F16, F16,
    F32,   // accumulate in fp32
    F16,   // CShuffle staging type
    PassThrough, PassThrough, PassThrough,
    kSpec,
    1,           // NumGemmKPrefetchStage
    256,         // BlockSize
    256, 128, 32,  // MPerBlock, NPerBlock, KPerBlock
    8, 8,        // AK1, BK1
    32, 32,      // MPerXDL, NPerXDL
    4, 2,        // MXdlPerWave, NXdlPerWave
    S<4, 64, 1>, S<1, 0, 2>, S<1, 0, 2>, 2, 8, 8, 1,
    S<4, 64, 1>, S<1, 0, 2>, S<1, 0, 2>, 2, 8, 8, 1,
    1, 1, S<1, 32, 1, 8>, 8>;

}  // namespace

torch::Tensor run(const torch::Tensor& A, const torch::Tensor& B) {
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == torch::kHalf && B.scalar_type() == torch::kHalf,
              "fp16 only");
  TORCH_CHECK(A.size(1) == B.size(1), "K mismatch");

  auto a = A.contiguous();
  auto b = B.contiguous();
  const int64_t M = a.size(0), K = a.size(1), N = b.size(0);
  auto c = torch::empty({M, N}, a.options());

  auto gemm = DeviceGemmInstance{};
  auto argument = gemm.MakeArgument(
      static_cast<const F16*>(a.data_ptr()),
      static_cast<const F16*>(b.data_ptr()),
      static_cast<F16*>(c.data_ptr()),
      static_cast<ck::index_t>(M), static_cast<ck::index_t>(N),
      static_cast<ck::index_t>(K),
      static_cast<ck::index_t>(K),   // StrideA: row-major A, ld = K
      static_cast<ck::index_t>(K),   // StrideB: column-major B, ld = K
      static_cast<ck::index_t>(N),   // StrideC: row-major C, ld = N
      PassThrough{}, PassThrough{}, PassThrough{});

  if (!gemm.IsSupportedArgument(argument)) {
    throw std::runtime_error(
        "CK instance does not support this shape: " + gemm.GetTypeString());
  }

  auto invoker = gemm.MakeInvoker();
  // time_kernel = false: the harness owns the timing, and CK's own timer would
  // both synchronize and launch extra iterations inside the measured region.
  invoker.Run(argument, StreamConfig{c10::hip::getCurrentHIPStream(), false});
  return c;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("run", &run, "GEMM n128 k2048 fp16 via Composable Kernel (ck seed)");
}
